const cache = new Map()

// "/" at a domain root, "/astroforeveryone/" on GitHub Pages
export const BASE = import.meta.env.BASE_URL

// generated pages use root paths (/images/…, /tools/…, /events); point them at wherever the site is served
export const withBase = (html) => html.replace(/(src|href)="\/(?!\/)/g, `$1="${BASE}`)

// page bodies are generated by build_site.py from the two original sites (trusted, our own content)
export function loadPage(slug) {
  if (!cache.has(slug)) {
    cache.set(slug, fetch(`${BASE}content/${slug}.json`).then((r) => (r.ok ? r.json() : null)).catch(() => null))
  }
  return cache.get(slug)
}
